bool isPossible(vector<int>& boards, int k, int maxLen) {
    int painters = 1, current = 0;
    for (int len : boards) {
        if (current + len <= maxLen) {
            current += len;
        } else {
            painters++;
            current = len;
            if (painters > k) return false;
        }
    }
    return true;
}

