    cout << "modSub: " << modSub(b, a) << "\n";
    cout << "modMul: " << modMul(a, b) << "\n";
    cout << "modPow(2, 100): " << modPow(2, 100) << "\n";
    cout << "modInv(5): " << modInv(5) << "\n";
    cout << "modDiv(10, 5): " << modDiv(10, 5) << "\n";

    return 0;
}

