    }
    return res;
}

// Catalan numbers using recurrence
long long catalan(int n) {
    if (n <= 1) return 1;
    long long C = 1;  // C(0)
    for (int i = 0; i < n; i++) {
        C = C * 2 * (2*i + 1) % MOD;
        C = C * modPow(i + 2, MOD - 2) % MOD;
    }
    return C;
}

// Direct formula: C(2n, n) / (n+1)
long long catalanDirect(int n) {
    // Precompute factorials up to 2n
    vector<long long> fact(2*n + 1);
    fact[0] = 1;
    for (int i = 1; i <= 2*n; i++) fact[i] = fact[i-1] * i % MOD;
    long long c2n_n = fact[2*n] * modPow(fact[n], MOD-2) % MOD * modPow(fact[n], MOD-2) % MOD;
    return c2n_n * modPow(n + 1, MOD - 2) % MOD;
}

int main() {
