#include <bits/stdc++.h>
using namespace std;

vector<char> segmentedSieve(long long L, long long R) {
    long long lim = sqrt(R);
    vector<char> mark(lim + 1, true);
    vector<long long> primes;

    // Generate base primes up to sqrt(R)
    for (long long i = 2; i <= lim; i++) {
        if (mark[i]) {
            primes.push_back(i);
            for (long long j = i * i; j <= lim; j += i) {
                mark[j] = false;
            }
        }
    }

    // Process segments
    const int S = 100000;  // segment size
    vector<char> isPrime(R - L + 1, true);

    for (long long p : primes) {
        long long start = max(p * p, (L + p - 1) / p * p);
        for (long long j = start; j <= R; j += p) {
            isPrime[j - L] = false;
        }
    }

    if (L == 1) isPrime[0] = false;

    return isPrime;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long L = 1e12, R = 1e12 + 1000;
    auto isPrime = segmentedSieve(L, R);

    cout << "Primes in range [" << L << ", " << R << "]: ";
    int count = 0;
    for (int i = 0; i <= R - L; i++) {
        if (isPrime[i]) {
            cout << (L + i) << " ";
            count++;
        }
    }
    cout << "\nCount: " << count << "\n";

    return 0;
}

