const int MAXN = 1e7;
vector<char> is_prime;
vector<int> primeCount;  // prefix sum

void buildPrefix() {
    is_prime.assign(MAXN + 1, true);
    is_prime[0] = is_prime[1] = false;

    for (int i = 2; i * i <= MAXN; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= MAXN; j += i) {
                is_prime[j] = false;
            }
        }
    }

    primeCount.resize(MAXN + 1);
    for (int i = 1; i <= MAXN; i++) {
        primeCount[i] = primeCount[i-1] + (is_prime[i] ? 1 : 0);
    }
}

