        System.out.println("Last modified: " + Files.getLastModifiedTime(path));

        // Copy and move
        Path copy = Paths.get("modern_copy.txt");
        Files.copy(path, copy, StandardCopyOption.REPLACE_EXISTING);

        // Delete
        Files.deleteIfExists(copy);
    }
}

import java.nio.file.*;

public class DirectoryWalk {
    public static void main(String[] args) throws Exception {
        Path start = Paths.get(".");

        // List immediate contents
        System.out.println("=== Directory Listing ===");
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(start)) {
            for (Path entry : stream) {
                System.out.println((Files.isDirectory(entry) ? "[DIR]  " : "[FILE] ") + entry.getFileName());
            }
        }

        // Walk entire tree (recursive)
        System.out.println("\n=== All Java Files ===");
        Files.walk(start, 2)
             .filter(p -> p.toString().endsWith(".java"))
             .forEach(System.out::println);
    }
}

