#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<pair<int,int>>> adj(n);  // {neighbor, weight}
    vector<int> indeg(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        indeg[v]++;
    }

    // Kahn's topo sort
    queue<int> q;
    for (int i = 0; i < n; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        for (auto& [v, w] : adj[u]) {
            if (--indeg[v] == 0) q.push(v);
        }
    }

    // DP on topo order
    vector<long long> dist(n, LLONG_MIN);
    dist[topo[0]] = 0;
    long long ans = 0;

    for (int u : topo) {
        if (dist[u] == LLONG_MIN) continue;
        for (auto& [v, w] : adj[u]) {
            if (dist[u] + w > dist[v]) {
                dist[v] = dist[u] + w;
                ans = max(ans, dist[v]);
            }
        }
    }

    cout << "Longest path: " << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, src;
    cin >> n >> m >> src;
    vector<vector<pair<int,int>>> adj(n);  // {neighbor, weight}

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].push_back({v, w});
        adj[v].push_back({u, w});  // Remove for directed
    }

    const long long INF = 1e18;
    vector<long long> dist(n, INF);
    vector<int> parent(n, -1);

    // Min-heap: {distance, node}
    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
    dist[src] = 0;
    pq.push({0, src});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        if (d > dist[u]) continue;  // Skip outdated entries

        for (auto& [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                pq.push({dist[v], v});
            }
        }
    }

    cout << "Shortest distances from " << src << ":\n";
    for (int i = 0; i < n; i++) {
        cout << i << " -> " << (dist[i] == INF ? -1 : dist[i]) << "\n";
    }

    // Reconstruct path to target
    int target = n - 1;
    if (dist[target] != INF) {
        vector<int> path;
        for (int v = target; v != -1; v = parent[v])
            path.push_back(v);
        reverse(path.begin(), path.end());
        cout << "Path to " << target << ": ";
        for (int v : path) cout << v << " ";
        cout << "\n";
    }

    return 0;
}

