        st.erase(it);

        for (auto& [v, w] : adj[u]) {
            if (dist[u] + w < dist[v]) {
                if (dist[v] != INF) st.erase({dist[v], v});
                dist[v] = dist[u] + w;
                st.insert({dist[v], v});
            }
        }
    }

    for (int i = 0; i < n; i++) {
        cout << dist[i] << " ";
    }
    cout << "\n";

    return 0;
}

