    }

    // Check for negative cycles
    bool hasNegCycle = false;
    for (auto& e : edges) {
        if (dist[e.u] != INF && dist[e.u] + e.w < dist[e.v]) {
            hasNegCycle = true;
            break;
        }
    }

    if (hasNegCycle) {
        cout << "Negative cycle detected!\n";
    } else {
        cout << "Shortest distances from " << src << ":\n";
        for (int i = 0; i < n; i++) {
            cout << i << " -> " << (dist[i] == INF ? -1 : dist[i]) << "\n";
        }
