int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    adj.resize(n);
    adjT.resize(n);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adjT[v].push_back(u);  // Transpose
    }

    // Pass 1: Order by finish time
    vis.assign(n, false);
    for (int i = 0; i < n; i++) {
        if (!vis[i]) dfs1(i);
    }

    // Pass 2: DFS on transpose in reverse order
    vis.assign(n, false);
    vector<vector<int>> sccs;

    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        if (!vis[u]) {
            comp.clear();
            dfs2(u);
            sccs.push_back(comp);
        }
