    cout << "Number of SCCs: " << sccs.size() << "\n";
    for (auto& c : sccs) {
        cout << "{ ";
        for (int x : c) cout << x << " ";
        cout << "}\n";
    }

    // Condensation graph
    vector<int> sccId(n);
    for (int i = 0; i < sccs.size(); i++) {
        for (int x : sccs[i]) sccId[x] = i;
    }

    set<pair<int,int>> condEdges;
    for (int u = 0; u < n; u++) {
        for (int v : adj[u]) {
            if (sccId[u] != sccId[v]) {
                condEdges.insert({sccId[u], sccId[v]});
            }
        }
    }

    cout << "Condensation edges: ";
    for (auto& [u, v] : condEdges) cout << "(" << u << "," << v << ") ";
    cout << "\n";

    return 0;
}

