vector<vector<int>> adj;
vector<int> disc, low, sccId;
vector<bool> inStack;
stack<int> st;
int timer = 0, sccCount = 0;

void tarjan(int u) {
    disc[u] = low[u] = ++timer;
    st.push(u);
    inStack[u] = true;

    for (int v : adj[u]) {
        if (disc[v] == 0) {
            tarjan(v);
            low[u] = min(low[u], low[v]);
        } else if (inStack[v]) {
            low[u] = min(low[u], disc[v]);
        }
    }

    if (low[u] == disc[u]) {
        // u is root of an SCC
        sccCount++;
        while (true) {
            int x = st.top(); st.pop();
            inStack[x] = false;
            sccId[x] = sccCount;
            if (x == u) break;
        }
    }
}

