#include <bits/stdc++.h>
using namespace std;

struct TwoSAT {
    int n;
    vector<vector<int>> adj, adjT;
    vector<bool> vis;
    vector<int> order, comp, assignment;

    TwoSAT(int _n) {
        n = _n;
        adj.resize(2 * n);
        adjT.resize(2 * n);
    }

    // x = true/false, returns node index
    int var(int x, bool val) { return 2 * x + val; }

    // Add implication: if u then v
    void addImplication(int u, int v) {
        adj[u].push_back(v);
        adjT[v].push_back(u);
    }

    // Add OR clause: (x = a) OR (y = b)
    void addOr(int x, bool a, int y, bool b) {
        addImplication(var(x, !a), var(y, b));
        addImplication(var(y, !b), var(x, a));
    }

    // Add XOR: exactly one of x, y is true
    void addXor(int x, int y) {
        addOr(x, true, y, true);
        addOr(x, false, y, false);
    }

    void dfs1(int u) {
        vis[u] = true;
        for (int v : adj[u]) if (!vis[v]) dfs1(v);
        order.push_back(u);
    }

    void dfs2(int u, int cl) {
        comp[u] = cl;
        for (int v : adjT[u]) if (comp[v] == -1) dfs2(v, cl);
    }

    bool solve() {
        vis.assign(2 * n, false);
        for (int i = 0; i < 2 * n; i++) {
            if (!vis[i]) dfs1(i);
        }

        comp.assign(2 * n, -1);
        int j = 0;
        for (int i = 2 * n - 1; i >= 0; i--) {
            int u = order[i];
            if (comp[u] == -1) dfs2(u, j++);
        }

        assignment.resize(n);
        for (int i = 0; i < n; i++) {
            if (comp[2*i] == comp[2*i+1]) return false;
            assignment[i] = comp[2*i] > comp[2*i+1];
        }
        return true;
    }
};

