                low[u] = min(low[u], low[v]);
                if (low[v] > disc[u]) {
                    result.push_back({u, v});
                }
            } else {
                low[u] = min(low[u], disc[v]);
            }
        }
    }

public:
    vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {
        adj.resize(n);
        disc.assign(n, 0);
        low.assign(n, 0);

        for (auto& e : connections) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }

        dfs(0, -1);
        return result;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n = 4;
    vector<vector<int>> connections = {{0,1},{1,2},{2,0},{1,3}};

    Solution sol;
    auto bridges = sol.criticalConnections(n, connections);

    cout << "Critical connections: ";
    for (auto& e : bridges) {
        cout << "(" << e[0] << "," << e[1] << ") ";
    }
    cout << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

// Top-down (Memoization)
long long fibMemo(int n, vector<long long>& dp) {
    if (n <= 1) return n;
    if (dp[n] != -1) return dp[n];
    return dp[n] = (fibMemo(n-1, dp) + fibMemo(n-2, dp)) % MOD;
}

// Bottom-up (Tabulation)
long long fibTab(int n) {
    if (n <= 1) return n;
    vector<long long> dp(n + 1);
    dp[0] = 0; dp[1] = 1;
    for (int i = 2; i <= n; i++) {
        dp[i] = (dp[i-1] + dp[i-2]) % MOD;
    }
    return dp[n];
}

// Space-optimized (O(1) space)
long long fibSpaceOpt(int n) {
    if (n <= 1) return n;
    long long a = 0, b = 1, c;
    for (int i = 2; i <= n; i++) {
        c = (a + b) % MOD;
        a = b;
        b = c;
    }
    return b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> dp(n + 1, -1);
    cout << "Memoization: " << fibMemo(n, dp) << "\n";
    cout << "Tabulation: " << fibTab(n) << "\n";
    cout << "Space optimized: " << fibSpaceOpt(n) << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // dp[i] = ways to reach step i
    vector<long long> dp(n + 1);
    dp[0] = 1;  // One way to be at ground
    dp[1] = 1;  // One way to reach step 1

    for (int i = 2; i <= n; i++) {
        dp[i] = (dp[i-1] + dp[i-2]) % MOD;
    }

    cout << "Ways to climb " << n << " stairs: " << dp[n] << "\n";

    // Generalized: can take 1, 2, or 3 steps
    vector<long long> dp2(n + 1);
    dp2[0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int step = 1; step <= 3 && i - step >= 0; step++) {
            dp2[i] = (dp2[i] + dp2[i - step]) % MOD;
        }
    }
    cout << "Ways with 1/2/3 steps: " << dp2[n] << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    if (n == 0) { cout << "0\n"; return 0; }
    if (n == 1) { cout << a[0] << "\n"; return 0; }

    // dp[i] = max loot from first i houses
    long long prev2 = 0;      // dp[i-2]
    long long prev1 = a[0];   // dp[i-1]

    for (int i = 1; i < n; i++) {
        long long curr = max(prev1, prev2 + a[i]);
        prev2 = prev1;
        prev1 = curr;
    }

    cout << "Max loot: " << prev1 << "\n";

    // Circular version (first and last are adjacent)
    // Run twice: exclude first, exclude last
    auto linearRob = [&](int l, int r) -> long long {
        if (l > r) return 0;
        long long p2 = 0, p1 = a[l];
        for (int i = l + 1; i <= r; i++) {
            long long curr = max(p1, p2 + a[i]);
            p2 = p1;
            p1 = curr;
        }
        return p1;
    };

    long long circular = max(linearRob(0, n-2), linearRob(1, n-1));
    cout << "Circular max: " << circular << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    // dp[i] = max subarray sum ending at i
    vector<long long> dp(n);
    dp[0] = a[0];
    long long ans = a[0];
    int start = 0, end = 0, tempStart = 0;

    for (int i = 1; i < n; i++) {
        if (dp[i-1] + a[i] > a[i]) {
            dp[i] = dp[i-1] + a[i];
        } else {
            dp[i] = a[i];
            tempStart = i;
        }

        if (dp[i] > ans) {
            ans = dp[i];
            start = tempStart;
            end = i;
        }
    }

    cout << "Max subarray sum: " << ans << "\n";
    cout << "Subarray: [" << start << "," << end << "]\n";

    // O(1) space version
    long long maxSoFar = a[0], maxEndingHere = a[0];
    for (int i = 1; i < n; i++) {
        maxEndingHere = max((long long)a[i], maxEndingHere + a[i]);
        maxSoFar = max(maxSoFar, maxEndingHere);
    }
    cout << "Space optimized: " << maxSoFar << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<vector<int>> grid(n, vector<int>(m));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) cin >> grid[i][j];
    }

    // dp[i][j] = min path sum to reach (i,j)
    vector<vector<long long>> dp(n, vector<long long>(m));
    dp[0][0] = grid[0][0];

    // First row
    for (int j = 1; j < m; j++) dp[0][j] = dp[0][j-1] + grid[0][j];
    // First column
    for (int i = 1; i < n; i++) dp[i][0] = dp[i-1][0] + grid[i][0];

    for (int i = 1; i < n; i++) {
        for (int j = 1; j < m; j++) {
            dp[i][j] = grid[i][j] + min(dp[i-1][j], dp[i][j-1]);
        }
    }

    cout << "Min path sum: " << dp[n-1][m-1] << "\n";

    // Reconstruct path
    vector<pair<int,int>> path;
    int i = n-1, j = m-1;
    while (i > 0 || j > 0) {
        path.push_back({i, j});
        if (i == 0) j--;
        else if (j == 0) i--;
        else if (dp[i-1][j] < dp[i][j-1]) i--;
        else j--;
    }
    path.push_back({0, 0});
    reverse(path.begin(), path.end());

    cout << "Path: ";
    for (auto& [x, y] : path) cout << "(" << x << "," << y << ") ";
    cout << "\n";

    return 0;
}
